# generate all candidate triples (a,b,c) with a<b and a+b=c
candidates = []
for a, b in itertools.combinations(sorted(L), 2):
    c = a + b
    if c in L and c not in (a, b):
        candidates.append((a, b, c))
# exact cover search
used = set()
solution = []
found = False

def backtrack(start, used, sol):
    global found, solution
    if found:
        return
    if len(used) == len(L):
        found = True
        solution = sol.copy()
        return
    # pick smallest unused element to branch on
    remaining = sorted(L - used)
